module Chips
  class VIC
    PALETTE = [0x000000, 0xffffff, 0x924a40, 0x84c5cc].freeze
    attr_accessor :palette
  end
end

module Theme
  BRIGHT = Chips::VIC::PALETTE[1]
  BACKGROUND = Chips::VIC::PALETTE[2]
  COLORS = [Chips::VIC::PALETTE[2], Chips::VIC::PALETTE[3]].freeze
end

class Scope
  def draw(x, color) = puts("#{x} #{color.to_s(16)}")
end

class View
  BRIGHT = Theme::BRIGHT

  def initialize = @scope = Scope.new
  def voice(i) = @scope.draw(i, Theme::COLORS[i])
  def output = @scope.draw(8, Theme::BRIGHT)
  def alias_output = @scope.draw(9, BRIGHT)

  def back
    b = Theme::BACKGROUND
    p [(b >> 16) & 0xff, (b >> 8) & 0xff, b & 0xff]
  end
end

vic = Chips::VIC.new
vic.palette = Chips::VIC::PALETTE
v = View.new
v.voice(0)
v.voice(1)
v.output
v.alias_output
v.back
p aaa
